type Json = Record<string, any>;
type Block = { id?: number; clientId: string; block_type: string; content_json: Json; answer_key_json: Json | null; settings_json: Json | null; skill?: 'READING' | 'SPEAKING' | 'LISTENING' | 'WRITING' | 'MIXED'; points: number; position: number; required: boolean; grading_mode: 'AUTO' | 'TEACHER' | 'AI_ASSISTED' };
